    <script>
        const sbMenuButton=document.querySelector('#sb-menu'),sbNav=document.querySelector('#sb-nav');
        sbMenuButton.addEventListener('click',()=>{const isOpen=sbMenuButton.getAttribute('aria-expanded')==='true';sbMenuButton.setAttribute('aria-expanded',String(!isOpen));sbMenuButton.setAttribute('aria-label',isOpen?'Buka menu':'Tutup menu');sbNav.classList.toggle('open',!isOpen)});
        sbNav.querySelectorAll('a').forEach(link=>link.addEventListener('click',()=>{sbNav.classList.remove('open');sbMenuButton.setAttribute('aria-expanded','false');sbMenuButton.setAttribute('aria-label','Buka menu')}));
        const sbSafe=(tag,className,text)=>{const element=document.createElement(tag);if(className)element.className=className;element.textContent=text;return element};
        const sbMoney=value=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(value||0);
        const sbBudgetYear=document.querySelector('#sb-budget-year'),sbBudgetList=document.querySelector('#sb-budget-list'),sbBudgetLabel=document.querySelector('#sb-budget-year-label');
        fetch('/api/desa/sebaung/budgets').then(response=>response.ok?response.json():Promise.reject()).then(budgets=>{if(!budgets.length)return;sbBudgetYear.hidden=false;budgets.forEach(item=>{const option=document.createElement('option');option.value=item.year;option.textContent=String(item.year);sbBudgetYear.append(option)});const render=()=>{const budget=budgets.find(item=>String(item.year)===String(sbBudgetYear.value));if(!budget)return;sbBudgetLabel.textContent=String(budget.year);sbBudgetList.replaceChildren();[['Pendapatan',budget.revenue],['Belanja',budget.expenditure],['Pembiayaan',budget.financing],['Realisasi',budget.realized],['Dana Desa',budget.villageFund]].forEach(([label,value])=>{const row=document.createElement('div');row.className='sb-budget-row';row.append(sbSafe('span','',label),sbSafe('strong','',value?sbMoney(value):'Belum tersedia'));sbBudgetList.append(row)})};sbBudgetYear.value=String(budgets[0].year);sbBudgetYear.addEventListener('change',render);render()}).catch(()=>{});
        const sbFilters=document.querySelector('#sb-project-filters'),sbProjectList=document.querySelector('#sb-project-list'),sbFilterYear=document.querySelector('#sb-project-year'),sbFilterStatus=document.querySelector('#sb-project-status'),sbFilterLocation=document.querySelector('#sb-project-location');let sbProjects=[];
        function sbRenderProjects(){const filters=[['year',sbFilterYear.value],['status',sbFilterStatus.value],['location',sbFilterLocation.value]];const visible=sbProjects.filter(project=>filters.every(([key,value])=>!value||String(project[key]||'')===value));sbProjectList.replaceChildren();if(!visible.length){sbProjectList.append(sbSafe('p','sb-project-empty','Belum ada informasi pembangunan yang dapat ditampilkan.'));return}visible.forEach((project,index)=>{const row=document.createElement('article');row.className='sb-project';row.append(sbSafe('span','sb-project-no',String(index+1).padStart(2,'0')));const content=document.createElement('div');const meta=document.createElement('div');meta.className='sb-project-meta';[project.year,project.location,project.status].filter(Boolean).forEach(value=>meta.append(sbSafe('span','',String(value))));content.append(meta,sbSafe('h3','',project.title||'Kegiatan desa'),sbSafe('p','',project.summary||project.description||'Rincian belum tersedia.'));const end=document.createElement('div');end.className='sb-project-end';end.append(sbSafe('strong','',project.funding||'Anggaran belum tersedia'));row.append(content,end);sbProjectList.append(row)});}
        fetch('/api/desa/sebaung/content').then(response=>response.ok?response.json():Promise.reject()).then(data=>{sbProjects=Array.isArray(data.projects)?data.projects:[];if(!sbProjects.length){sbRenderProjects();return}[['year',sbFilterYear],['status',sbFilterStatus],['location',sbFilterLocation]].forEach(([key,select])=>{const values=[...new Set(sbProjects.map(project=>String(project[key]||'')).filter(Boolean))].sort();values.forEach(value=>{const option=document.createElement('option');option.value=value;option.textContent=value;select.append(option)})});sbFilters.hidden=false;sbFilters.addEventListener('change',sbRenderProjects);sbFilters.addEventListener('reset',event=>{event.preventDefault();[sbFilterYear,sbFilterStatus,sbFilterLocation].forEach(select=>select.value='');sbRenderProjects()});sbRenderProjects()}).catch(()=>{});
        const sbQuestions=[{key:'title',prompt:'Apa usulan yang ingin disampaikan?',required:true,type:'text'},{key:'location',prompt:'Di mana usulan ini diperlukan?',required:true,type:'text'},{key:'category',prompt:'Pilih bidang usulan.',required:false,type:'choice',options:['Infrastruktur','Lingkungan','Sosial','Ekonomi','Lainnya']},{key:'description',prompt:'Jelaskan usulan secara singkat.',required:true,type:'textarea'},{key:'name',prompt:'Nama (opsional).',required:false,type:'text'},{key:'contact',prompt:'Kontak yang bisa dihubungi (opsional).',required:false,type:'text'}];let sbAnswers={},sbStep=0;const sbChat=document.querySelector('#sb-chat'),sbMessages=document.querySelector('#sb-chat-messages'),sbControls=document.querySelector('#sb-chat-controls'),sbActions=document.querySelector('#sb-chat-actions'),sbError=document.querySelector('#sb-chat-error'),sbToggle=document.querySelector('#sb-chat-toggle');
        function sbSay(text,isUser=false){sbMessages.append(sbSafe('div',`sb-chat-message${isUser?' is-user':''}`,text));sbChat.querySelector('.sb-chat-body').scrollTop=sbChat.querySelector('.sb-chat-body').scrollHeight}function sbAction(label,handler,primary=false){const button=sbSafe('button',primary?'primary':'',label);button.type='button';button.addEventListener('click',handler);return button}function sbCloseChat(reset=true){sbChat.classList.remove('open');sbChat.setAttribute('aria-hidden','true');sbToggle.setAttribute('aria-expanded','false');if(reset){sbAnswers={};sbStep=0;sbMessages.replaceChildren();sbControls.replaceChildren();sbActions.replaceChildren();sbError.textContent=''}}
        function sbRenderQuestion(){sbControls.replaceChildren();sbActions.replaceChildren();sbError.textContent='';if(sbStep>=sbQuestions.length){sbSay('Periksa kembali usulan sebelum dikirim.');sbSay(`${sbAnswers.title}\n${sbAnswers.location}\n${sbAnswers.description}`);sbActions.append(sbAction('Batal',()=>sbCloseChat()),sbAction('Kirim usulan',sbSubmitProposal,true));return}const question=sbQuestions[sbStep];sbSay(question.prompt);sbControls.append(sbSafe('div','sb-chat-prompt',`${sbStep+1} dari ${sbQuestions.length}`));if(question.type==='choice'){const options=document.createElement('div');options.className='sb-chat-options';question.options.forEach(option=>options.append(sbAction(option,()=>{sbAnswers[question.key]=option;sbSay(option,true);sbStep++;sbRenderQuestion()})));sbControls.append(options)}else{const input=document.createElement(question.type==='textarea'?'textarea':'input');input.className='sb-chat-input';input.placeholder=question.key==='title'?'Judul usulan':question.key==='location'?'Lokasi':question.key==='description'?'Uraian singkat':question.key==='name'?'Nama':'Kontak';input.setAttribute('aria-label',input.placeholder);input.maxLength=question.key==='description'?3000:160;if(question.type==='textarea')input.rows=3;sbControls.append(input)}sbActions.append(sbAction('Batal',()=>sbCloseChat()));if(!question.required)sbActions.append(sbAction('Lewati',()=>{sbAnswers[question.key]='';sbStep++;sbRenderQuestion()}));sbActions.append(sbAction(sbStep===sbQuestions.length-1?'Tinjau':'Lanjut',()=>{const input=sbControls.querySelector('input,textarea'),value=input?.value.trim()||'';if(question.required&&!value){sbError.textContent='Bagian ini perlu diisi.';return}sbAnswers[question.key]=value;if(value)sbSay(value,true);sbStep++;sbRenderQuestion()},true))}
        async function sbSubmitProposal(){sbError.textContent='';const send=sbActions.querySelector('.primary');send.disabled=true;try{const response=await fetch('/api/desa/sebaung/proposals',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content},body:JSON.stringify({...sbAnswers,website:''})});const result=response.status===204?{}:await response.json();if(!response.ok)throw new Error(result.message||'Usulan belum berhasil dikirim.');sbMessages.replaceChildren();sbControls.replaceChildren();sbActions.replaceChildren();sbSay(result.message||'Usulan berhasil dikirim.');sbActions.append(sbAction('Selesai',()=>sbCloseChat(),true))}catch(exception){sbError.textContent=exception.message;send.disabled=false}}
        sbToggle.addEventListener('click',()=>{const open=!sbChat.classList.contains('open');sbChat.classList.toggle('open',open);sbChat.setAttribute('aria-hidden',String(!open));sbToggle.setAttribute('aria-expanded',String(open));if(open&&!sbMessages.childElementCount)sbRenderQuestion()});document.querySelector('#sb-chat-close').addEventListener('click',()=>sbCloseChat(false));
    </script>
    @include('desa.partials.responsive')
</body>
</html>
